package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.View;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Detail and guarded mutation screen for a single RouterOS resource. */
public final class ResourceDetailActivity extends Activity {private String section,kind,id,name,profile;private TextView status,details;private EditText profileInput;private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean running;private final int NAVY=Color.rgb(22,47,80),BLUE=Color.rgb(23,103,177);
 @Override public void onCreate(Bundle b){super.onCreate(b);section=getIntent().getStringExtra("section");kind=getIntent().getStringExtra("kind");id=getIntent().getStringExtra("id");name=getIntent().getStringExtra("name");profile=getIntent().getStringExtra("profile");build();}
 private void build(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(20,20,20,30);p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);p.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(p);setContentView(s); UiTheme.apply(this);TextView t=txt("تفاصيل المورد",23);p.addView(t);details=txt(name+"\nالمعرف: "+id+"\nالباقة: "+profile,15);p.addView(details);status=txt("جاهز",14);p.addView(status);if("active".equals(kind)){button(p,"فصل الجلسة",()->confirm("فصل الجلسة",()->mutate("disconnect")));}else if(!"profiles".equals(kind)){profileInput=new EditText(this);profileInput.setHint("الباقة الجديدة");profileInput.setText(profile);p.addView(profileInput);button(p,"تعديل الباقة",()->confirm("تعديل الباقة",()->mutate("update")));button(p,"تفعيل/تعطيل",()->confirm("تغيير الحالة",()->mutate("toggle")));button(p,"حذف المورد",()->confirm("حذف المورد",()->mutate("delete")));}}
 private void mutate(String action){if(running)return;running=true;status.setText("جاري التحقق من المورد...");worker.execute(()->{try{SecureConnectionStore sec=new SecureConnectionStore(this);try(RouterService r=connect(sec)){if("hotspot".equals(section)){HotspotService x=new HotspotService(r);List<Map<String,String>> fresh="active".equals(kind)?x.active():x.users();Map<String,String> row=find(fresh);if("active".equals(kind))x.disconnect(id);else if("update".equals(action))x.updateUser(id,profileInput.getText().toString().trim());else if("toggle".equals(action))x.setDisabled(id,!"true".equalsIgnoreCase(row.getOrDefault("disabled","false")));else x.removeUser(id);}else{PppoeService x=new PppoeService(r);List<Map<String,String>> fresh="active".equals(kind)?x.active():x.secrets();Map<String,String> row=find(fresh);if("active".equals(kind))x.disconnect(id);else if("update".equals(action))x.updateSecret(id,profileInput.getText().toString().trim());else if("toggle".equals(action))x.setDisabled(id,!"true".equalsIgnoreCase(row.getOrDefault("disabled","false")));else x.removeSecret(id);}ui(()->{running=false;status.setText("تمت العملية وتحقق الرد");});}}catch(java.io.IOException e){ui(()->{running=false;status.setText("النتيجة غير مؤكدة أو المورد غير متاح: "+safe(e));});}catch(Exception e){ui(()->{running=false;status.setText("فشلت العملية: "+safe(e));});}});}
 private Map<String,String> find(List<Map<String,String>> rs)throws java.io.IOException{for(Map<String,String> r:rs)if(id!=null&&id.equals(r.get(".id")))return r;throw new java.io.IOException("المورد تغير أو لم يعد موجودًا");}private void confirm(String title,Runnable r){new AlertDialog.Builder(this).setTitle(title).setMessage("سيتم التنفيذ باستخدام المعرف "+id+" بعد إعادة قراءة المورد").setNegativeButton("إلغاء",null).setPositiveButton("تأكيد",(d,w)->r.run()).show();}private RouterService connect(SecureConnectionStore s)throws Exception{android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false));r.login(p.getString("user",""),s.get()==null?"":s.get());return r;}private void button(LinearLayout p,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(BLUE));b.setOnClickListener(v->r.run());p.addView(b);}private TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(NAVY);t.setPadding(8,10,8,10);return t;}private String safe(Exception e){return e.getMessage()==null?"خطأ غير معروف":e.getMessage();}private void ui(Runnable r){runOnUiThread(r);}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}}
